import { array } from "@ember/helper";
import { LinkTo } from "@ember/routing";
import DCookText from "discourse/ui-kit/d-cook-text";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

const ItemContent = <template>
  <div class="templates-content">
    <LinkTo
      class="template-item-source-link"
      @models={{array @template.slug @template.id}}
      @route="topic"
    >
      {{dIcon "crosshairs"}}
      {{i18n "templates.source"}}
    </LinkTo>
    <DCookText @rawText={{@template.content}} />
  </div>
</template>;

export default ItemContent;
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import ItemContent from "./item-content.gjs";

export default class DTemplatesItem extends Component {
  @action
  apply() {
    // run parametrized action to insert the template
    this.args.onInsertTemplate?.(this.args.template);

    ajax(`/discourse_templates/${this.args.template.id}/use`, {
      type: "POST",
    }).catch(popupAjaxError);
  }

  <template>
    <details class="template-item" id="template-item-{{@template.id}}">
      <summary class="template-item-title">
        <div class="template-item-title-text">{{@template.title}}</div>

        <div class="actions">
          <DButton
            class="templates-apply"
            @action={{this.apply}}
            @icon="far-clipboard"
          />
        </div>
      </summary>

      <ItemContent @template={{@template}} />
    </details>
  </template>
}
import { action, computed } from "@ember/object";
import TagDrop from "discourse/select-kit/components/tag-drop";

export default class DTemplatesTagDrop extends TagDrop {
  @computed("availableTags.[]")
  get topTags() {
    // sort tags descending by count and ascending by name
    return (this.availableTags || []).sort((a, b) => {
      if (a.count !== b.count) {
        return b.count - a.count;
      } // descending
      if (a.name !== b.name) {
        return a.name < b.name ? -1 : 1;
      } // ascending
      return 0;
    });
  }

  search(filter) {
    return (this.content || [])
      .map((tag) => {
        if (tag.id && tag.name) {
          return tag;
        }
        return this.defaultItem(tag, tag);
      })
      .filter((tag) => {
        if (filter == null) {
          return true;
        }

        const tagFilter = filter.toLowerCase();
        return (
          tag.id.toLowerCase().includes(tagFilter) ||
          tag.name.toLowerCase().includes(tagFilter)
        );
      });
  }

  @action
  onChange(tagId, tag) {
    // overrides the action onChange of the parent with the value received in
    // the property onChangeSelectedTag in the handlebars template
    this.onChangeSelectedTag?.(tagId, tag);
  }
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action, computed } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import { schedule } from "@ember/runloop";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import { bind } from "discourse/lib/decorators";
import {
  ALL_TAGS_ID,
  NO_TAG_ID,
} from "discourse/select-kit/components/tag-drop";
import DConditionalLoadingSpinner from "discourse/ui-kit/d-conditional-loading-spinner";
import DTextField from "discourse/ui-kit/d-text-field";
import { i18n } from "discourse-i18n";
import Item from "./item.gjs";
import TagDrop from "./tag-drop.js";

const PREV_TEMPLATE_TAG_ID = "template-selected-tag";

export default class DTemplatesFilterableList extends Component {
  @service siteSettings;
  @service keyValueStore;

  @tracked loading = true;
  @tracked listFilter = "";
  @tracked replies = [];
  @tracked selectedTag = ALL_TAGS_ID;
  @tracked availableTags = [];

  @computed("availableTags.[]", "selectedTag")
  get selectedTagObject() {
    if (!this.selectedTag || this.selectedTag === ALL_TAGS_ID) {
      return null;
    }

    if (this.selectedTag === NO_TAG_ID) {
      return { name: NO_TAG_ID };
    }

    return (
      this.availableTags.find((tag) => tag.id === this.selectedTag) || {
        name: this.selectedTag,
      }
    );
  }

  @computed("replies", "selectedTag", "listFilter")
  get filteredReplies() {
    const filterTitle = this.listFilter.toLowerCase();
    return (
      this.replies
        .map((template) => {
          /* Give a relevant score to each template. */
          template.score = 0;
          if (template.title.toLowerCase().includes(filterTitle)) {
            template.score += 2;
          } else if (template.content.toLowerCase().includes(filterTitle)) {
            template.score += 1;
          }
          return template;
        })
        // Filter irrelevant replies.
        .filter((template) => template.score !== 0)
        // Filter only replies tagged with the selected tag.
        .filter((template) => {
          if (this.selectedTag === ALL_TAGS_ID) {
            return true;
          }
          if (this.selectedTag === NO_TAG_ID && template.tags.length === 0) {
            return true;
          }

          return template.tags.includes(this.selectedTag);
        })
        .sort((a, b) => {
          /* Sort replies by relevance, usage, and title. */
          if (a.score !== b.score) {
            return a.score > b.score ? -1 : 1; /* descending */
          } else if (a.usages !== b.usages) {
            return a.usages > b.usages ? -1 : 1; /* descending */
          } else if (a.title !== b.title) {
            return a.title < b.title ? -1 : 1; /* ascending */
          }
          return 0;
        })
    );
  }

  @bind
  async load() {
    try {
      this.loading = true;

      const results = await ajax("/discourse_templates");
      this.replies = results.templates;

      if (this.siteSettings.tagging_enabled) {
        this.availableTags = Object.values(
          this.replies.reduce((availableTags, template) => {
            template.tags.forEach((tag) => {
              if (availableTags[tag]) {
                availableTags[tag].count += 1;
              } else {
                availableTags[tag] = { id: tag, name: tag, count: 1 };
              }
            });

            return availableTags;
          }, {})
        );

        const prevSelectedTag = this.keyValueStore.get(PREV_TEMPLATE_TAG_ID);
        if (
          prevSelectedTag &&
          (prevSelectedTag === NO_TAG_ID ||
            this.availableTags.find((t) => t.id === prevSelectedTag))
        ) {
          this.selectedTag = prevSelectedTag;
        } else {
          this.keyValueStore.remove(PREV_TEMPLATE_TAG_ID);
        }
      }
    } catch (e) {
      this.loading = false;
      popupAjaxError(e);
    } finally {
      this.loading = false;

      schedule("afterRender", () =>
        document.querySelector(".templates-filter")?.focus()
      );
    }
  }

  @action
  changeSelectedTag(tagId) {
    this.selectedTag = tagId;
    if (tagId === ALL_TAGS_ID) {
      this.keyValueStore.remove(PREV_TEMPLATE_TAG_ID);
      return;
    }
    this.keyValueStore.set({ key: PREV_TEMPLATE_TAG_ID, value: tagId });
  }

  @action
  insertTemplate(template) {
    this.args.onBeforeInsertTemplate?.();
    this.args.onInsertTemplate?.(template);
    this.args.onAfterInsertTemplate?.();
  }

  <template>
    <div class="templates-filterable-list" {{didInsert this.load}}>

      <DConditionalLoadingSpinner @condition={{this.loading}}>
        <div class="templates-filter-bar">
          {{#if this.siteSettings.tagging_enabled}}
            <TagDrop
              @availableTags={{this.availableTags}}
              @onChangeSelectedTag={{this.changeSelectedTag}}
              @tag={{this.selectedTagObject}}
            />
          {{/if}}
          <DTextField
            class="templates-filter"
            placeholder={{i18n "templates.filter_hint"}}
            @value={{this.listFilter}}
          />
        </div>
        <div class="templates-list">
          {{#each this.filteredReplies as |r|}}
            <Item
              @model={{@model}}
              @onInsertTemplate={{this.insertTemplate}}
              @template={{r}}
            />
          {{/each}}
        </div>
      </DConditionalLoadingSpinner>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import DModal from "discourse/ui-kit/d-modal";
import { i18n } from "discourse-i18n";
import FilterableList from "../filterable-list.gjs";

export default class Form extends Component {
  @service appEvents;

  constructor() {
    super(...arguments);
    if (this.args.closeModal) {
      this.appEvents.on("page:changed", this, this.args.closeModal);
    }
  }

  willDestroy() {
    super.willDestroy(...arguments);
    if (this.args.closeModal) {
      this.appEvents.off("page:changed", this, this.args.closeModal);
    }
  }

  <template>
    <DModal
      class="d-templates d-templates-modal"
      @closeModal={{@closeModal}}
      @title={{i18n "templates.insert_template"}}
    >
      <:body>
        <FilterableList
          @onAfterInsertTemplate={{@closeModal}}
          @onInsertTemplate={{@model.onInsertTemplate}}
          @textarea={{@model.textarea}}
        />
      </:body>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import DTemplatesModalForm from "../../components/d-templates/modal/form.gjs";

export default class DTemplatesModalContainer extends Component {
  @service dTemplatesModal;

  <template>
    {{#if this.dTemplatesModal.model}}
      <div class="modal-container d-templates-modal-container">
        <DTemplatesModalForm
          @closeModal={{this.dTemplatesModal.hide}}
          @model={{this.dTemplatesModal.model}}
        />
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DButton from "discourse/ui-kit/d-button";
import FilterableList from "../../components/d-templates/filterable-list.gjs";

const SELECTOR_EDITOR_PREVIEW =
  "#reply-control .d-editor-preview-wrapper > .d-editor-preview";

export default class DTemplatesEditorPreview extends Component {
  static shouldRender(args, context) {
    return !context.site.mobileView;
  }

  @service appEvents;

  @tracked templatesVisible = false;
  @tracked onInsertTemplate;

  constructor() {
    super(...arguments);

    this.appEvents.on("discourse-templates:show", this, "show");
    this.appEvents.on("discourse-templates:hide", this, "hide");
  }

  willDestroy() {
    super.willDestroy(...arguments);

    this.appEvents.off("discourse-templates:show", this, "show");
    this.appEvents.off("discourse-templates:hide", this, "hide");
  }

  @action
  show({ onInsertTemplate }) {
    const elemEditorPreview = document.querySelector(SELECTOR_EDITOR_PREVIEW);
    if (elemEditorPreview) {
      elemEditorPreview.style.display = "none";
    }

    this.onInsertTemplate = onInsertTemplate;
    this.templatesVisible = true;
  }

  @action
  hide() {
    const elemEditorPreview = document.querySelector(SELECTOR_EDITOR_PREVIEW);
    if (elemEditorPreview) {
      elemEditorPreview.style.display = "";
    }

    this.templatesVisible = false;
  }

  <template>
    <div class="d-templates" ...attributes>
      {{#if this.templatesVisible}}
        <div class="d-templates-container">
          <DButton
            class="modal-close close btn-flat"
            @action={{this.hide}}
            @icon="xmark"
          />
          <FilterableList
            @onAfterInsertTemplate={{this.hide}}
            @onInsertTemplate={{this.onInsertTemplate}}
          />
        </div>
      {{/if}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import discourseDebounce from "discourse/lib/debounce";
import Category from "discourse/models/category";
import DButton from "discourse/ui-kit/d-button";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

const TEMPLATE_OPTIONS_START_REGEX = /^\s*<!--\s*discourse-template\s*/i;
const TEMPLATE_OPTIONS_BODY_SEPARATOR_REGEX = /^([ \t]*\r?\n){1,2}/;
const TEMPLATE_OPTIONS_MAX_LENGTH = 500;

export default class DiscourseTemplatesButton extends Component {
  static shouldRender(outletArgs, helper) {
    return outletArgs.model.is_template && helper.currentUser?.can_create_topic;
  }

  @service composer;

  @tracked copyConfirm = false;

  async fetchRaw() {
    const topic = this.args.outletArgs.model;
    return await ajax(`/raw/${topic.id}/1`, { dataType: "text" });
  }

  parseTemplateOptions(raw) {
    const header = raw.slice(0, TEMPLATE_OPTIONS_MAX_LENGTH);
    const startMatch = header.match(TEMPLATE_OPTIONS_START_REGEX);

    if (!startMatch) {
      return { body: raw };
    }

    const headerEnd = header.indexOf("-->", startMatch[0].length);

    if (headerEnd === -1) {
      return { body: raw };
    }

    const options = {};
    raw
      .slice(startMatch[0].length, headerEnd)
      .split("\n")
      .forEach((line) => {
        const [, key, value] = line.match(/^\s*([\w-]+)\s*:\s*(.*?)\s*$/) || [];

        if (key && value) {
          options[key] = value;
        }
      });

    return {
      body: raw
        .slice(headerEnd + 3)
        .replace(TEMPLATE_OPTIONS_BODY_SEPARATOR_REGEX, ""),
      categorySlug: options.category,
      tags: options.tags
        ?.split(",")
        .map((tag) => tag.trim())
        .filter(Boolean)
        .join(","),
    };
  }

  async findCategory(categorySlug) {
    if (!categorySlug) {
      return null;
    }

    const slugPath = categorySlug.split(/[/:]/).filter(Boolean);

    let category = Category.findBySlugPath(slugPath);

    if (!category?.canCreateTopic) {
      category = await Category.asyncFindBySlugPath(slugPath.join("/")).catch(
        () => null
      );
    }

    return category?.canCreateTopic ? category : null;
  }

  @action
  async createNewTopic() {
    const template = this.parseTemplateOptions(await this.fetchRaw());
    const category = await this.findCategory(template.categorySlug);

    this.composer.openNewTopic({
      body: template.body,
      category,
      tags: template.tags,
    });
  }

  @action
  async copy() {
    const text = await this.fetchRaw();
    navigator.clipboard.writeText(text);
    this.copyConfirm = true;
    discourseDebounce(this.resetCopyButton, 2000);
  }

  @action
  resetCopyButton() {
    this.copyConfirm = false;
  }

  <template>
    <div class="template-topic-controls">
      <DButton
        class={{dConcatClass
          "btn-default"
          "template-copy"
          (if this.copyConfirm "ok")
        }}
        @action={{this.copy}}
        @icon={{if this.copyConfirm "check" "copy"}}
        @label="templates.copy"
      />
      <DButton
        class="btn-default template-new-topic"
        @action={{this.createNewTopic}}
        @icon="plus"
        @label="templates.new_topic"
      />
    </div>
  </template>
}
export default function extractVariablesFromChatChannel(
  channel,
  message,
  router
) {
  if (!channel && !message) {
    return {};
  }

  const inReplyTo = message?.inReplyTo;

  const channelVariables = {
    chat_channel_name: channel?.title,
    chat_channel_url: channel?.routeModels
      ? router?.urlFor("chat.channel", ...channel.routeModels)
      : null,
    reply_to_username: inReplyTo?.user?.username,
    reply_to_name: inReplyTo?.user?.name,
  };

  return {
    ...channelVariables,
    context_title: channelVariables.chat_channel_name,
    context_url: channelVariables.chat_channel_url,
  };
}
import extractVariablesFromChatChannel from "./variables-chat-channel.js";

export default function extractVariablesFromChatThread(
  thread,
  message,
  router
) {
  if (!thread && !message) {
    return {};
  }

  const channel = thread?.channel;
  const inReplyTo = thread?.originalMessage;

  const channelVariables = extractVariablesFromChatChannel(
    channel,
    message,
    router
  );

  const threadVariables = {
    chat_thread_name: thread?.title,
    chat_thread_url: thread?.routeModels
      ? router?.urlFor("chat.channel.thread", ...thread.routeModels)
      : null,
    reply_to_username: inReplyTo?.user?.username,
    reply_to_name: inReplyTo?.user?.name,
  };

  return {
    ...channelVariables,
    ...threadVariables,
    context_title:
      threadVariables.chat_thread_name || channelVariables.chat_channel_name,
    context_url:
      threadVariables.chat_thread_url || channelVariables.chat_channel_url,
  };
}
import { withPluginApi } from "discourse/lib/plugin-api";
import { PLATFORM_KEY_MODIFIER } from "discourse/services/keyboard-shortcuts";
import extractVariablesFromChatChannel from "../../lib/variables-chat-channel.js";
import extractVariablesFromChatThread from "../../lib/variables-chat-thread.js";

export default {
  name: "discourse-templates-add-ui-builder",

  initialize(container) {
    const siteSettings = container.lookup("service:site-settings");
    const currentUser = container.lookup("service:current-user");

    if (
      siteSettings.discourse_templates_enabled &&
      currentUser?.can_use_templates
    ) {
      withPluginApi((api) => {
        addOptionsMenuItem(api);
        addKeyboardShortcut(api, container);
        addChatIntegration(api, container);
      });
    }
  },
};

function addOptionsMenuItem(api) {
  const dTemplates = api.container.lookup("service:d-templates");

  api.addComposerToolbarPopupMenuOption({
    icon: "far-clipboard",
    label: "templates.insert_template",
    action: () => {
      dTemplates.showComposerUI();
    },
  });
}

const _templateShortcutTargets = [];

function addKeyboardShortcut(api, container) {
  api.addKeyboardShortcut(
    `${PLATFORM_KEY_MODIFIER}+shift+i`,
    (event) => {
      event.preventDefault();
      const dTemplates = container.lookup("service:d-templates");

      if (dTemplates.isComposerFocused) {
        dTemplates.showComposerUI();
        return;
      }

      for (const target of _templateShortcutTargets) {
        if (
          dTemplates.isTextAreaFocused &&
          target?.isFocused?.(document.activeElement)
        ) {
          dTemplates.showTextAreaUI(target?.variables);
          return;
        }
      }

      if (dTemplates.isTextAreaFocused) {
        dTemplates.showTextAreaUI();
      }
    },
    {
      global: true,
      help: {
        category: "templates",
        name: "templates.insert_template",
        definition: {
          keys1: [PLATFORM_KEY_MODIFIER, "shift", "i"],
          keysDelimiter: "plus",
        },
      },
    }
  );
}

function addChatIntegration(api, container) {
  if (!container.lookup("service:chat")?.userCanChat) {
    return;
  }

  const channelVariablesExtractor = function () {
    const chat = container.lookup("service:chat");
    const activeChannel = chat?.activeChannel;
    const currentMessage = activeChannel?.draft;
    const router = container.lookup("service:router");

    return extractVariablesFromChatChannel(
      activeChannel,
      currentMessage,
      router
    );
  };

  const threadVariablesExtractor = function () {
    const chat = container.lookup("service:chat");
    const activeThread = chat?.activeChannel?.activeThread;
    const currentMessage = activeThread?.draft;
    const router = container.lookup("service:router");

    return extractVariablesFromChatThread(activeThread, currentMessage, router);
  };

  // add a custom chat composer button
  api.registerChatComposerButton({
    id: "d-templates-chat-insert-template-btn",
    icon: "far-clipboard",
    label: "templates.insert_template",
    position: "dropdown",
    action: function () {
      let contextVariablesExtractor;
      switch (this.context) {
        case "channel":
          contextVariablesExtractor = channelVariablesExtractor.bind(this);
          break;
        case "thread":
          contextVariablesExtractor = threadVariablesExtractor.bind(this);
          break;
        default:
          contextVariablesExtractor = null;
      }

      const textarea = this.composer?.textarea?.textarea; // this.composer.textarea is a TextareaInteractor instance

      container
        .lookup("service:d-templates")
        .showTextAreaUI(contextVariablesExtractor, textarea);
    },
    displayed() {
      return (
        this.composer?.textarea &&
        (this.context === "channel" || this.context === "thread")
      );
    },
  });

  // add custom keyboard shortcut handlers for the chat channel composer and chat thread composer
  _templateShortcutTargets.push(
    {
      isFocused: (element) => element?.id === "channel-composer",
      variables: channelVariablesExtractor,
    },
    {
      isFocused: (element) => element?.id === "thread-composer",
      variables: threadVariablesExtractor,
    }
  );
}
import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-templates";

export default {
  name: "templates-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.setAdminPluginIcon(PLUGIN_ID, "far-clipboard");
    });
  },
};
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import Service from "@ember/service";

export default class DTemplatesModalService extends Service {
  @tracked model = null;

  @action
  show(model) {
    this.model = model;
  }

  @action
  hide() {
    // return the focus back to the textarea
    this.model?.textarea?.focus();

    // clear the model
    this.model = null;
  }
}
import User from "discourse/models/user";

// keep this list synchronized with the list in spec/plugin_helper.rb
export const TEMPLATES_ALLOWED_VARIABLES = Object.freeze([
  "my_username",
  "my_name",
  "chat_channel_name",
  "chat_channel_url",
  "chat_thread_name",
  "chat_thread_url",
  "context_title",
  "context_url",
  "topic_title",
  "topic_url",
  "original_poster_username",
  "original_poster_name",
  "reply_to_username",
  "reply_to_name",
  "last_poster_username",
  "reply_to_or_last_poster_username",
]);

export function replaceVariables(title, content, modelVariables) {
  const currentUser = User.current();
  const variables = {
    ...(modelVariables || {}),
    my_username: currentUser?.username,
    my_name: currentUser?.displayName,
  };

  if (variables && typeof variables === "object") {
    for (const key of TEMPLATES_ALLOWED_VARIABLES) {
      if (variables[key]) {
        title = title.replace(
          new RegExp(`%{${key}(,fallback:.[^}]*)?}`, "g"),
          variables[key]
        );
        content = content.replace(
          new RegExp(`%{${key}(,fallback:.[^}]*)?}`, "g"),
          variables[key]
        );
      } else {
        title = title.replace(
          new RegExp(`%{${key},fallback:(.[^}]*)}`, "g"),
          "$1"
        );
        title = title.replace(new RegExp(`%{${key}}`, "g"), "");
        content = content.replace(
          new RegExp(`%{${key},fallback:(.[^}]*)}`, "g"),
          "$1"
        );
        content = content.replace(new RegExp(`%{${key}}`, "g"), "");
      }
    }
  }

  return { title, content };
}
export default function extractVariablesFromComposerModel(model) {
  if (!model) {
    return {};
  }

  const composerVariables = {
    topic_title: model.topic?.title,
    topic_url: model.topic?.url,
    original_poster_username: model.topic?.details.created_by.username,
    original_poster_name: model.topic?.details.created_by.name,
    reply_to_username: model.post?.username,
    reply_to_name: model.post?.name,
    last_poster_username: model.topic?.last_poster_username,
    reply_to_or_last_poster_username:
      model.post?.username || model.topic?.last_poster_username,
  };

  return {
    ...composerVariables,
    context_title: composerVariables.topic_title,
    context_url: composerVariables.topic_url,
  };
}
import { getOwner } from "@ember/owner";
import Service, { service } from "@ember/service";
import TextareaTextManipulation from "discourse/lib/textarea-text-manipulation";
import { replaceVariables } from "../../lib/replace-variables.js";
import extractVariablesFromComposerModel from "../../lib/variables-composer.js";

export default class DTemplatesService extends Service {
  @service appEvents;
  @service modal;
  @service site;
  @service currentUser;
  @service dTemplatesModal;
  @service composer;

  get isComposerFocused() {
    const activeElement = document.activeElement;

    const composerModel = getOwner(this).lookup("service:composer").model;
    const composerElement = document.querySelector(".d-editor");

    return composerModel && composerElement?.contains(activeElement);
  }

  get isTextAreaFocused() {
    return this.#isTextArea(document.activeElement);
  }

  showComposerUI() {
    const onInsertTemplate = this.#insertTemplateIntoComposer.bind(this);

    if (this.site.mobileView || !this.composer.isPreviewVisible) {
      this.#showModal(null, onInsertTemplate); // textarea must be empty when targeting the composer
    } else {
      this.#showComposerPreviewUI(onInsertTemplate);
    }
  }

  showTextAreaUI(variablesExtractor = null, textarea = document.activeElement) {
    if (!this.#isTextArea(textarea)) {
      return;
    }

    const modal = document.querySelector(".d-modal");
    const onInsertTemplate = this.#insertTemplateIntoTextArea.bind(this);
    const extractVariables = (model) => variablesExtractor?.(model);

    if (modal?.contains(textarea)) {
      if (!modal.classList.contains("d-templates")) {
        this.#showModal(textarea, (template) => {
          const modalModel = this.modal.activeModal?.opts?.model;
          onInsertTemplate(textarea, template, extractVariables(modalModel));
        });
      }
    } else {
      this.#showModal(textarea, (template) =>
        onInsertTemplate(textarea, template, extractVariables())
      );
    }
  }

  #isTextArea(element) {
    return element?.nodeName === "TEXTAREA";
  }

  #showModal(textarea, onInsertTemplate) {
    this.dTemplatesModal.show({ textarea, onInsertTemplate });
  }

  #showComposerPreviewUI(onInsertTemplate) {
    this.appEvents.trigger("composer-messages:close");
    this.appEvents.trigger("composer:show-preview");
    this.appEvents.trigger("discourse-templates:show", { onInsertTemplate });
  }

  #insertTemplateIntoTextArea(textarea, template, variables) {
    template = this.#replaceTemplateVariables(
      template.title,
      template.content,
      variables
    );

    new TextareaTextManipulation(getOwner(this), { textarea }).insertBlock(
      template.content
    );
  }

  #insertTemplateIntoComposer(template) {
    const composerModel = getOwner(this).lookup("service:composer").model;
    const templateVariables = extractVariablesFromComposerModel(composerModel);

    template = this.#replaceTemplateVariables(
      template.title,
      template.content,
      templateVariables
    );

    // insert the title if blank
    if (composerModel && !composerModel.title) {
      composerModel.set("title", template.title);
    }

    // insert the content of the template in the composer
    this.appEvents.trigger("composer:insert-block", template.content);
  }

  #replaceTemplateVariables(title, content, variables = {}) {
    return replaceVariables(title, content, {
      ...variables,
      my_username: this.currentUser?.username,
      my_name: this.currentUser?.displayName,
    });
  }
}
